import React from "react";
import './css/index.css'
import { withRouter } from "react-router-dom/cjs/react-router-dom.min";
function Particular(props) {
  return (
      <div className="container text-center text-container" style={{ marginTop:'20vh'}}>
        <h2 className="text-primary fw-semibold">
          4-135 <span className="text-white">宿舍管理系统</span>
        </h2>
        <p className="mt-4 fs-5 ">
          一个轻量、实用的宿舍水电费管理系统。支持多人分摊、按居住天数计算、缴费记录管理，帮助宿舍成员清晰、公平地分摊水电费用
        </p>
        <button className="mt-5 btn btn-primary text-white" onClick={()=>{props.history.push('/bill')}}>开始查看账单</button>
      </div>
  );
}
export default withRouter(Particular)
